/// <summary>
/// COC For default process posting.
/// </summary>
/// <param name = "_recordSet">Record set</param>
/// <param name = "_documentStatus">Document status</param>
/// <param name = "_releaseToSalesFormLetter">Boolean value</param>
protected void defaultProcessPosting(Set _recordSet, CredManDocumentStatusCheck _documentStatus, boolean _releaseToSalesFormLetter)
{
    _releaseToSalesFormLetter = false;
    next defaultProcessPosting(_recordSet, _documentStatus, _releaseToSalesFormLetter);
    this.releaseMETCreditCheckPoint();
}

/// <summary>
/// COC for releaseMETCreditCheckPoint
/// </summary>
public void releaseMETCreditCheckPoint()
{
    CredManTable credManTable = callerBuffer as CredManTable;
    CredManTable::releaseFromCreditControl(
        credManTable.SalesId,
        releaseReasonId,
        NoYes::No,
        NoYes::Yes,
        credManTable.Company);
}
